"""Generate language constants for signed multi-server transport limits."""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

from codex_layout import REPOSITORY_ROOT
from codex_multi_server_transport_limits import (
    MULTI_SERVER_MAX_REQUEST_BYTES,
    MULTI_SERVER_MAX_RESPONSE_BYTES,
)


OUTPUTS = {
    REPOSITORY_ROOT / "workspaces/runtime/apps/server/src/generated/multi_server_transport_limits.mjs": (
        "// Generated by studio_api.generate_multi_server_transport_limits.\n"
        f"export const MULTI_SERVER_MAX_REQUEST_BYTES = {MULTI_SERVER_MAX_REQUEST_BYTES};\n"
        f"export const MULTI_SERVER_MAX_RESPONSE_BYTES = {MULTI_SERVER_MAX_RESPONSE_BYTES};\n"
    ),
    REPOSITORY_ROOT / "workspaces/runtime/packages/runtime-services/src/multi_server_transport_limits.rs": (
        "// Generated by studio_api.generate_multi_server_transport_limits.\n"
        f"pub const MAX_REQUEST_BYTES: usize = {MULTI_SERVER_MAX_REQUEST_BYTES};\n"
        f"pub const MAX_RESPONSE_BYTES: usize = {MULTI_SERVER_MAX_RESPONSE_BYTES};\n"
    ),
}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--write", action="store_true", help="write generated constants")
    mode.add_argument("--check", action="store_true", help="fail when outputs are stale")
    args = parser.parse_args(argv)
    for path, expected in OUTPUTS.items():
        if args.check:
            try:
                current = path.read_text(encoding="utf-8")
            except (OSError, UnicodeError):
                current = None
            if current != expected:
                print(
                    f"{path.relative_to(REPOSITORY_ROOT)} is stale; "
                    "run `pnpm run multi-server-limits:generate`",
                    file=sys.stderr,
                )
                return 1
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
